import java.util.*;

class Solution {
  public int twoSumLessThanK(int[] nums, int k) {
    Arrays.sort(nums);
    int best = -1;
    for (int l = 0, r = nums.length - 1; l < r; ) {
      int sum = nums[l] + nums[r];
      if (sum < k) {
        best = Math.max(best, sum);
        l++;
      } else r--;
    }
    return best;
  }
}
